#!/usr/bin/env python3
"""Generate the offline city selector from the reviewed, source-attributed dataset."""
from pathlib import Path
import json
p=Path(__file__).resolve().parents[1];rows=json.loads((p/'design/cities-national.json').read_text())['provinces']
cities=[];starts=[];counts=[]
for r in rows:
 starts.append(len(cities));counts.append(len(r['cities']));cities.extend(r['cities'])
assert len(rows)==34 and all(0<n<256 for n in counts)
assert all(len(c['name'].encode())<49 and 15<c['latitude']<55 and 72<c['longitude']<136 for c in cities)
s=['#pragma once','#include <stdint.h>','namespace rlcd_clock {','struct City { const char *name; int32_t latitude,longitude; };','// Generated by tools/generate_cities.py; sources: design/cities-national.json.',f'static constexpr unsigned PROVINCE_COUNT={len(rows)};',f'static constexpr unsigned CITY_COUNT={len(cities)};','static constexpr const char *PROVINCES[]={'+','.join(json.dumps(r['name'],ensure_ascii=False) for r in rows)+'};','static constexpr unsigned CITY_STARTS[]={'+','.join(map(str,starts))+'};','static constexpr unsigned CITY_COUNTS[]={'+','.join(map(str,counts))+'};','static constexpr City CITIES[]={']
s+=['  {'+json.dumps(c['name'],ensure_ascii=False)+','+str(round(c['latitude']*1e6))+','+str(round(c['longitude']*1e6))+'},' for c in cities];s+=['};','}']
(p/'main/ClockCities.h').write_text('\n'.join(s)+'\n');print(f'{len(rows)} provinces; {len(cities)} weather locations')
